const { useState } = React;

function Counter() {
  const [count, setCount] = useState(0);

  document.title = '클릭 ' + count + '회';

  return (
    <button type="button" onClick={() => setCount(count + 1)}>
      클릭 {count}회
    </button>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<Counter />);

